def build_prompt(question: str, candidates: list[str]) -> str:
    top = rerank(question, candidates, keep=6)  # fewer, better chunks
    docs = "\n\n".join(
        f'<doc id="{i}">\n{c}\n</doc>' for i, c in enumerate(edge_order(top))
    )
    return f"<documents>\n{docs}\n</documents>\n\nQuestion: {question}"
